for i,(a,b,scene,shot,purpose) in enumerate(raw):
 shots.append({'index':i,'start':a,'end':b,'scene':scene,'shot':shot,'purpose':purpose,'camera':'Street: original3D orthographic track. Drawn locations: layered isometric tracking with foreground occlusion; closeups stay still longer.','foreground':'rails/columns/record edges where applicable','midground':'performer or detail subject','background':'location architecture or paper field','transition':'selected paper wipe / vinyl iris / clean cut; subtitle area stays undistorted','effects':['brief print-registration offset','limited silhouette afterimage','paper edge wipe'] if i in [2,8,15,16,25,26] else []})
